<html lang="en">
<head>
<meta charset="utf-8">
<title>Neon Neural Growth</title>
<style>
  html, body { margin: 0; height: 100%; background: #05070f; overflow: hidden; }
  body { display: flex; align-items: center; justify-content: center; }
  canvas { width: 800px; height: 800px; background: #05070f; box-shadow: 0 0 40px rgba(0,229,255,0.15); }
